\set ON_ERROR_STOP on
begin;
delete from coverage_rule where document_id = (select id from program_document where id::text like 'fd00e728%');
with d as (select id, insurance_company_id from program_document where id::text like 'fd00e728%')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause)
select d.id, d.insurance_company_id, 'Правила банкоканала (НС/здоровье, не мед-ДМС)', v.sc, v.sp, v.vd, v.ct, v.la, v.cl
from d cross join (values
('стоматология-терапия','лечение зубов имплантация удаление восстановление','excluded','ПРАВИЛА БАНКОКАНАЛА (продукт НС, не мед-ДМС): лечение зубов не признаётся страховым случаем, ЗА ИСКЛЮЧЕНИЕМ повреждений, полученных в результате несчастного случая',null,'п. 4.2.1'),
('стоматология-терапия','лечение зубов при несчастном случае','conditional','покрывается только если повреждение зубов получено в результате несчастного случая в срок страхования',null,'п. 4.6.13'),
('стоматология-хирургия','перелом вывих постоянного зуба альвеолярный отросток','conditional','выплата по таблице: 1% страховой суммы за зуб, максимум 10% при множественных повреждениях','1% (макс. 10%)','Таблица выплат «Повреждение зубов» (а)'),
('стоматология-хирургия','потеря постоянного зуба опорного для протеза','conditional','выплата по таблице: 2% страховой суммы за зуб, максимум 20% при множественной потере','2% (макс. 20%)','Таблица выплат «Повреждение зубов» (б)'),
('стоматология-хирургия','потеря части челюсти вместе с зубами','conditional','выплата по таблице: 25% (часть челюсти без альвеолярного отростка) или 30% (челюсть с зубами)','25-30%','Таблица выплат «потеря части челюсти»'),
('протезирование','протезирование имплантация определение','conditional','в этих Правилах «Протезирование или имплантация» — комплекс услуг по замене отсутствующих/нефункционирующих органов или частей тела',null,'Раздел 1 «Протезирование или имплантация — Комплекс медицинских услуг»'),
('общие-исключения','умышленное причинение себе вреда противоправные действия','excluded',null,null,'п. 4.1.1'),
('общие-исключения','алкогольное наркотическое токсическое отравление','excluded','включая заболевания, вызванные употреблением алкоголя/наркотиков',null,'п. 4.1.2'),
('общие-исключения','спид вич-инфекция','excluded',null,null,'п. 4.1.3'),
('общие-исключения','хронические нервные психические расстройства эпилепсия диспансерный учёт','excluded',null,null,'п. 4.1.4'),
('общие-исключения','места лишения свободы военная служба судебное решение','excluded','кроме сотрудников пенитенциарных учреждений',null,'п. 4.1.5 – 4.1.7'),
('общие-исключения','беременность роды аборт стерилизация бесплодие','excluded',null,null,'п. 4.6.12 – 4.6.14'),
('общие-исключения','пластические косметические вмешательства','excluded','кроме устранения последствий телесных повреждений от несчастного случая в срок страхования',null,'п. 4.6.13'),
('общие-исключения','заболевания костно-мышечной системы соединительной ткани','excluded',null,null,'п. 4.6.11'),
('общие-условия','нетрудоспособность или госпитализация по исключённым основаниям','excluded','ОРВИ, пищевая токсикоинфекция (кроме повлёкших госпитализацию), диагностика методами биопсии/эндоскопии/лапароскопии/артроскопии, уход за ребёнком или членом семьи',null,'п. 4.2.1')
) as v(sc, sp, vd, ct, la, cl);
select count(*) as alfa_bank from coverage_rule where document_id = (select id from program_document where id::text like 'fd00e728%');
commit;
